        } else if (cupom.equals("MENOS50")) {
            return arredondar(BigDecimal.valueOf(50));
        } else if (cupom.equals("FRETEGRATIS")) {
            return arredondar(frete);
        } else if (cupom.equals("LEVE3PAGUE2")) {
