        ModalidadeEntrega modalidade = ModalidadeEntrega.valueOf(request.getModalidadeEntrega());
        String cupomCod = request.getCupom();
        FormaPagamento formaPagamento = FormaPagamento.valueOf(request.getFormaPagamento());
