    private BigDecimal calcularValorParcela(BigDecimal totalFinal, Integer parcelas, FormaPagamento formaPagamento) {
        BigDecimal parcela = totalFinal.divide(BigDecimal.valueOf(parcelas), 10, RoundingMode.HALF_EVEN);
